package localization

// Russian is the complete built-in Russian user-interface catalog.
type Russian struct{}

// Text resolves a Russian string and makes missing translations visible
// without leaking the internal localization key into the interface.
func (Russian) Text(key Key) string {
	if text, ok := russian[key]; ok {
		return text
	}
	return "[нет перевода]"
}

